import{_ as e,o as n,c as r,a as i}from"./app.f62c66af.js";const t={},a=i('<h1 id="gluhwein-pota" tabindex="-1"><a class="header-anchor" href="#gluhwein-pota" aria-hidden="true">#</a> Gl\xFChwein-POTA</h1><p>Am 05.12. findet deutschlandweit das traditionelle Winterfest der Drau\xDFenfunker statt.</p><h2 id="hamburg" tabindex="-1"><a class="header-anchor" href="#hamburg" aria-hidden="true">#</a> Hamburg</h2><p>In Hamburg treffen wir uns ab 11 Uhr im Hammer Park zu einer gemeinsamen Parks-On-The-Air-Aktivierung bei hei\xDFen Getr\xE4nken und knusprigem Weihnachtsgeb\xE4ck.</p><p>Wer Interesse am Portabelbetrieb oder einer gemeinsamen POTA-Aktivierung hat, ist herzlich eingeladen dazuzusto\xDFen. Portabelger\xE4te und Antennen f\xFCr Kurzwelle und UKW sind vorhanden und m\xFCssen nicht extra mitgebracht werden.</p><p>F\xFCr alle auf dem Weg zur Lizenz bieten wir Ausbildungsbetrieb auf UKW und Kurzwelle an, um direkt in den Funkbetrieb reinschnuppern zu k\xF6nnen.</p><p>W\xE4hrend wir im Park sind k\xF6nnt ihr uns auf 145.5 MHz und DM0NDR 2 m erreichen.</p><p>Auch wenn es hei\xDFe Getr\xE4nke gibt, denkt an warme Kleidung (Geheimtipp: lange Thermounterw\xE4sche).</p><p>Mehr Infos auf unter &quot;Aktivit\xE4ten&quot; oder im Discord.</p><p>73 Harm - DK4HAA und Ove - DK1BOU f\xFCr die Drau\xDFenfunker</p>',10),u=[a];function d(h,s){return n(),r("div",null,u)}var c=e(t,[["render",d],["__file","2026-12-05-Ankuendigung-Gluehwein-POTA.html.vue"]]);export{c as default};
